with open('src/components/contratos/contrato-impressao.tsx','r',encoding='utf-8') as f: s=f.read()
old = "                  <div><h1 className=\"text-lg font-bold\">{documento?.empresa?.nome_fantasia || documento?.empresa?.razao_social || \"Empresa\"}</h1>\n                  <p>{documento?.empresa?.razao_social}</p>\n                  <p>CNPJ: {documento?.empresa?.cnpj || \"Não informado\"}{documento?.empresa?.inscricao_estadual ? ` · IE: ${documento.empresa.inscricao_estadual}` : \"\"}</p>\n                  <p>{endereco(documento?.empresa)}</p>\n                  <p>{[documento?.empresa?.telefone, documento?.empresa?.email].filter(Boolean).join(\" · \")}</p></div>"
new = "                  <div>\n                    <h1 className=\"text-lg font-bold\">{documento?.empresa?.nome_fantasia || documento?.empresa?.razao_social || \"Empresa\"}</h1>\n                    <p>{documento?.empresa?.razao_social}</p>\n                    <p>CNPJ: {documento?.empresa?.cnpj || \"Não informado\"}{documento?.empresa?.inscricao_estadual ? ` · IE: ${documento.empresa.inscricao_estadual}` : \"\"}</p>\n                    <p>{endereco(documento?.empresa)}</p>\n                    <p>{[documento?.empresa?.telefone, documento?.empresa?.email].filter(Boolean).join(\" · \")}</p>\n                  </div>"
s = s.replace(old, new)
with open('src/components/contratos/contrato-impressao.tsx','w',encoding='utf-8') as f: f.write(s)
print('done', 'replaced' if old not in s else 'not replaced')
